"""Explicit authoring only: checked-in server geometry, never regenerated by CI."""
from datetime import datetime, timedelta, timezone
import json
from math import sin
from pathlib import Path
import sys
ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT/'backend'))
from app.engines import Bar
from app.intelligence.harmonics import GEOMETRY_CONTRACT_VERSION, harmonic_candidates
from app.intelligence.pivots import Pivot, confirmed_pivots, classic_patterns

START=datetime(2026,10,13,14,tzinfo=timezone.utc)
def points(prices,high=False):
    return [Pivot(i*10,p,'HIGH' if (high if i%2==0 else not high) else 'LOW',
        START+timedelta(minutes=i*10),START+timedelta(minutes=i*10+3),i*10+3) for i,p in enumerate(prices)]
def portable_points(ps):
    return [[p.index,p.confirmed_index,p.price,p.kind=='HIGH'] for p in ps]
def portable_harmonics(ps):
    results=[]
    for h in harmonic_candidates(ps):
        results.append({k:h[k] for k in ('kind','direction','mode','executable','ratios','activation','invalidation','targets')} | {
            'points':[[p['index'],p['confirmed_index'],p['price'],p['kind']=='HIGH'] for p in h['points'].values()],
            'przLow':h['prz']['low'],'przHigh':h['prz']['high'],
            'observedAt':max(p['confirmed_index'] for p in h['points'].values())})
    return results
def portable_classic(ps,close):
    result=classic_patterns(ps,close=close,as_of=ps[-1].confirmed_at)
    for p in result:
        p.pop('observed_at')
        if 'points' in p:
            p['points']=[[v['index'],v['confirmed_index'],v['price'],v['kind']=='HIGH'] for v in p['points']]
    return result

def main():
    harmonic=[];classic=[];bar_cases=[]
    cases={'GARTLEY':[100,200,138.2,176.3924,121.4],'BAT':[100,200,150,175,111.4],
        'BUTTERFLY':[100,200,121.4,160.7,72.8],'CRAB':[100,200,150,194.3,38.2],
        'CYPHER':[100,200,150,230,127.82],
        'WRONG_CD':[100,200,138.2,176.3924,180],'OUTSIDE_B':[100,200,250,270,150],
        'FAILED_RATIOS':[100,200,101,102,99],
        'BUTTERFLY_EXTENSION_RANGE':[100,200,121.4,188.8,55]}
    for name,prices in cases.items():
        for high in [False,True]:
            ps=points([400-p for p in prices] if high else prices,high)
            harmonic.append({'name':name+('_BEARISH' if high else '_BULLISH'),
                'points':portable_points(ps),'expected':portable_harmonics(ps)})
    for name,prices,high,close in [
        ('double top break',[200,180,201],True,179),('double top waiting',[200,180,201],True,190),
        ('double bottom break',[100,120,101],False,121),('double bottom waiting',[100,120,101],False,110),
        ('head shoulders',[200,180,220,185,201],True,179),('neckline must clear both',[200,180,220,185,201],True,183),
        ('inverse',[200,220,180,215,201],False,221),('triangle',[200,100,190,110,180,120],True,181),
        ('triangle waiting',[200,100,190,110,180,120],True,150),('not symmetric',[200,180,240],True,179)]:
        ps=points(prices,high);classic.append({'name':name,'points':portable_points(ps),'close':close,'expected':portable_classic(ps,close)})
    for name,count in [('oscillating',130),('flat',40),('plateau',40)]:
        closes=[100+5*sin(i/3) for i in range(count)] if name=='oscillating' else [100.]*count
        bars=[Bar(START+timedelta(minutes=i),c,c+.5,c-.5,c,1000) for i,c in enumerate(closes)]
        if name=='plateau':
            for i in [10,11]:bars[i]=Bar(bars[i].timestamp,100,105,99.5,100,1000)
        bar_cases.append({'name':name,'bars':[{'at':b.timestamp.isoformat(),'o':b.open,'h':b.high,'l':b.low,'c':b.close,'v':b.volume} for b in bars],
            'expected':portable_points(confirmed_pivots(bars,left=3,right=3))})
    for name,prices in [('gartley_source',cases['GARTLEY']),('butterfly_extension_source',cases['BUTTERFLY_EXTENSION_RANGE']),
                        ('bearish_cypher_source',[400-p for p in cases['CYPHER']])]:
        high=name.startswith('bearish')
        vertices=[(0,prices[0]+(-10 if high else 10))]+[(3+i*10,p) for i,p in enumerate(prices)]+[(48,prices[-1]+(-10 if high else 10))]
        bars=[]
        for i in range(49):
            a,b=next((a,b) for a,b in zip(vertices,vertices[1:]) if a[0]<=i<=b[0])
            c=a[1]+(b[1]-a[1])*(i-a[0])/(b[0]-a[0])
            bars.append(Bar(START+timedelta(minutes=i),c,c+.01,c-.01,c,1000))
        ps=confirmed_pivots(bars,left=3,right=3)
        assert portable_harmonics(ps),name
        bar_cases.append({'name':name,'bars':[{'at':b.timestamp.isoformat(),'o':b.open,'h':b.high,'l':b.low,'c':b.close,'v':b.volume} for b in bars],
            'expected':portable_points(ps),'harmonics':portable_harmonics(ps)})
    for name,prices,high,close in [
        ('classic_double_top_break',[200,180,201],True,179),('classic_double_top_wait',[200,180,201],True,190),
        ('classic_double_bottom',[100,120,101],False,121),('classic_head_shoulders',[200,180,220,185,201],True,179),
        ('classic_inverse',[200,220,180,215,201],False,221),('classic_triangle_wait',[200,100,190,110,180,120],True,150),
        ('classic_triangle_break',[200,100,190,110,180,120],True,181)]:
        last=3+(len(prices)-1)*10
        vertices=[(0,prices[0]+(-10 if high else 10))]+[(3+i*10,p) for i,p in enumerate(prices)]+[(last+13,close),(last+19,close)]
        bars=[]
        for i in range(last+20):
            a,b=next((a,b) for a,b in zip(vertices,vertices[1:]) if a[0]<=i<=b[0])
            c=a[1]+(b[1]-a[1])*(i-a[0])/(b[0]-a[0])
            bars.append(Bar(START+timedelta(minutes=i),c,c+.01,c-.01,c,1000))
        ps=confirmed_pivots(bars,left=3,right=3)
        expected=portable_classic(ps,close);assert expected,name
        bar_cases.append({'name':name,'bars':[{'at':b.timestamp.isoformat(),'o':b.open,'h':b.high,'l':b.low,'c':b.close,'v':b.volume} for b in bars],
            'expected':portable_points(ps),'classical':expected})
    path=ROOT/'mobile/test/fixtures/geometry_contract_v1.json'
    path.write_text(json.dumps({'contract':GEOMETRY_CONTRACT_VERSION,'harmonics':harmonic,'classical':classic,'bars':bar_cases},indent=2)+'\n')
    print(f'Authored18 harmonic,10 classic,{len(bar_cases)} bar-source cases')

if __name__=='__main__':main()
